//--------------------------------------------------------------------------//
//! \desc  In an RTOS environment, this server handles all public NVRAM 
//!        operations so as to encapsulate stack requirements and eliminate
//!        the caller needing to allocate extra stack memory.

//! \assume -none-

//! \notes  -none-

//  \param  -none-

//! \return \b void
//!

//! \throws \b none
//--------------------------------------------------------------------------//

#if NVRAM_USE_OS == 1

void nvram_tsk_server (void * _void_)
{
  for (;;)
    {
      Nvram_Op_Args * op_args ;

      Tsk tsk_client = os_msg_rcev (0 , & op_args , 0) ;

      ATOMIC (op_args->nvram_op_func (op_args)) ;

      os_msg_resp (tsk_client) ;
    }
}

#endif

